(()=>{
 const inputs=[['cam-yaw','yaw'],['cam-down','down'],['cam-z','z'],['cam-inset','inset'],['cam-spacing','spacing'],['cam-hfov','hfov'],['cam-vfov','vfov'],['cam-far','far'],['cam-recess','recess']];
 const fmt=(n,d=0)=>Number.isFinite(n)?n.toFixed(d):'—';
 function planSVG(a){const all=a.rows.flatMap(r=>r.groundPolygon),bound=Math.max(1100,...all.map(p=>p[0])),side=Math.max(500,...all.map(p=>Math.abs(p[1]))),s=Math.min(290/(bound+params.L/2),260/(2*side)),offset=25+(290-(bound+params.L/2)*s)/2,map=p=>[offset+(p[0]+params.L/2)*s,190-p[1]*s],path=p=>p.map((v,i)=>(i?'L':'M')+map(v).join(' ')).join(' ')+'Z';let out='<text x="20" y="24" fill="#66835a" font-size="11">지면 시야 투영 (좌) / 장착각 확대 (우) · 각 도식 별도 축척</text>';
  for(let x=0;x<=bound;x+=1000){const p=map([x,0]);out+=`<path d="M${p[0]} 45V322" stroke="#d8e1ce"/><text x="${p[0]}" y="342" text-anchor="middle" fill="#89967d" font-size="10">X ${x}</text>`;}
  a.rows.forEach((r,i)=>{if(r.groundPolygon.length)out+=`<path d="${path(r.groundPolygon)}" fill="${i?'#bdcb8c':'#80bbc6'}" fill-opacity=".22" stroke="${i?'#9cad6f':'#6ca4b1'}"/>`;});if(a.commonGround.length)out+=`<path d="${path(a.commonGround)}" fill="#5e9b81" fill-opacity=".18" stroke="#5e9b81" stroke-dasharray="4 3"/>`;
  const b1=map([-params.L/2,params.W/2]),b2=map([params.L/2,-params.W/2]);out+=`<rect x="${b1[0]}" y="${b1[1]}" width="${b2[0]-b1[0]}" height="${b2[1]-b1[1]}" rx="5" fill="#b4c3a9" stroke="#869d79"/><text x="${(b1[0]+b2[0])/2}" y="${b1[1]-10}" text-anchor="middle" fill="#61824e" font-size="10">5휠 베이스</text>`;
  for(const r of a.rows){const p=map(r.origin),end=map(r.origin.map((v,i)=>v+r.forward[i]*400));out+=`<path d="M${p.join(' ')}L${end.join(' ')}" stroke="#3f7c88" stroke-width="2"/><circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#2c6d79"/><text x="${end[0]}" y="${end[1]-8}" fill="#416e68" font-size="11">${r.side>0?'L':'R'} ${r.yaw>0?'+':''}${r.yaw}°</text>`;}
  const mini=p=>[520-p[1]*.29,223-p[0]*.29],miniPath=p=>p.map((v,i)=>(i?'L':'M')+mini(v).join(' ')).join(' ')+'Z',base=[[-params.L/2,-params.W/2],[params.L/2,-params.W/2],[params.L/2,params.W/2],[-params.L/2,params.W/2]];
  out+=`<path d="M355 45V345" stroke="#ccd8c0"/><text x="520" y="52" text-anchor="middle" font-size="11" fill="#668255">장착각 확대 / +X 전방 ↑</text><path d="${miniPath(base)}" fill="#d8e1cf" stroke="#a1b394"/><path d="M520 95V330" stroke="#a6b69b" stroke-dasharray="4 3"/>`;
  for(const f of cameraFrames()){const p=mini(f.origin),q=mini(f.origin.map((v,i)=>v+f.forward[i]*190)),body=[[-38,-45,0],[-2,-45,0],[-2,45,0],[-38,45,0]].map(v=>mPoint(f.matrix,v));out+=`<path d="${miniPath(body)}" fill="#7eaaa8" stroke="#4d8081"/><path d="M${p.join(' ')}L${q.join(' ')}" stroke="#3b7b86" stroke-width="2"/><circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#367680"/><text x="${q[0]}" y="${q[1]-6}" text-anchor="middle" font-size="11" fill="#4b7c70">${f.side>0?'L +':'R −'}${cameraDesign.yaw}°</text>`;}
  out+=`<text x="520" y="339" text-anchor="middle" font-size="10" fill="#7a8e6c">등가 광학 중심 Y ±${cameraDesign.spacing} / 높이 ${cameraDesign.z} mm</text>`;
  return out+'<text x="20" y="365" fill="#7d916e" font-size="10">色 영역은 가정 FOV·광축 깊이 안의 기하 투영입니다. 스테레오 매칭·거리 정확도·검출 성능을 뜻하지 않습니다.</text>'.replace('色','색');
 }
 function sideSVG(){const c=cameraDesign,s=.36,origin=[120,165-c.z*s],axisEnd=[origin[0]+300*Math.cos(c.down*Math.PI/180)*s,origin[1]+300*Math.sin(c.down*Math.PI/180)*s],bottomAngle=(c.down+c.vfov/2)*Math.PI/180,near=bottomAngle>0?c.z/Math.tan(bottomAngle):null,hit=near===null?null:[origin[0]+near*s,165];let out=`<text x="20" y="22" fill="#648154" font-size="11">광축 수직 평면 / 하향 + · 상향 − / 광학창과 브래킷 후보</text><path d="M25 165H670" stroke="#93a180"/><rect x="67" y="${origin[1]-12}" width="48" height="24" rx="3" fill="#87a9aa"/><circle cx="${origin[0]}" cy="${origin[1]}" r="4" fill="#2d727e"/><path d="M${origin.join(' ')}L${axisEnd.join(' ')}" stroke="#397f8d" stroke-width="2"/><text x="${axisEnd[0]+5}" y="${axisEnd[1]-5}" fill="#4d7f82" font-size="11">광축 ${c.down}°</text><path d="M120 165V${origin[1]}" stroke="#a9af94" stroke-dasharray="3 3"/><text x="25" y="${origin[1]+8}" fill="#718660" font-size="11">H ${c.z}</text>`;
  if(hit)out+=`<path d="M${origin.join(' ')}L${hit.join(' ')}" stroke="#a3b06a" stroke-width="2"/><text x="${hit[0]+8}" y="155" fill="#7f8b52" font-size="11">하단 시선 ${fmt(near)} mm</text>`;
  return out+'<text x="20" y="202" fill="#7a8d6c" font-size="10">하단 시선 교점은 광학 중심에서의 수평 거리입니다. 로봇 최전단 기준 거리는 평면 계산을 사용합니다.</text>';
 }
 window.renderCameraReview=()=>{const a=cameraAnalysis();for(const [id,key]of inputs){$(id).value=cameraDesign[key];$(id+'-out').textContent=cameraDesign[key]+(['yaw','down','hfov','vfov'].includes(key)?'°':' mm');}
  $('cam-brackets').checked=cameraDesign.brackets;$('cam-rays').checked=cameraDesign.rays;
  $('camera-plan').innerHTML=planSVG(a);$('camera-side').innerHTML=sideSVG();
  const distance=n=>n===null?'해당 없음':fmt(n)+' mm';
  $('camera-metrics').innerHTML=`<div><span>좌우 바깥쪽 요 / 가정</span><strong>±${cameraDesign.yaw}°</strong></div><div><span>중앙선 첫 지면 시야 / 최전단부터</span><strong>${distance(a.centerlineFirst)}</strong></div><div><span>광학창 테두리 여유 H / V</span><strong>${fmt(a.margins.horizontal,1)} / ${fmt(a.margins.vertical,1)} mm</strong></div>`;
  $('camera-packaging').innerHTML=a.packaging.map(p=>`<div class="${p.clear?'ok':'warn'}">${p.side>0?'L':'R'} · ${p.part} ↔ ${p.against}<strong>${fmt(p.gap,1)} mm</strong></div>`).join('');
  $('camera-register').innerHTML=a.rows.map(r=>`<tr><td>${r.side>0?'좌측 L':'우측 R'}</td><td>${r.origin.map(n=>fmt(n)).join(', ')}</td><td>${r.yaw}° / ${r.down}°</td><td>${r.forward.map(n=>fmt(n,3)).join(', ')}</td><td>${r.axisGround?r.axisGround.slice(0,2).map(n=>fmt(n)).join(', '):'지면 교점 없음'}</td></tr>`).join('');
  const warns=[];for(const p of a.packaging)if(!p.clear)warns.push((p.side>0?'L':'R')+' '+p.part+'–'+p.against+' 예약 간격 '+fmt(p.gap,1)+' mm / 기준 3 mm');if(a.margins.horizontal<2||a.margins.vertical<2)warns.push('가정 광학창의 테두리 여유 2 mm 미만');if(a.centerlineFirst===null)warns.push('설정한 깊이 안에서 중앙선 지면 시야 없음');if(cameraDesign.yaw>cameraDesign.hfov/2)warns.push('좌우 광축 벌어짐이 반시야각보다 큼');
  $('camera-assessment').textContent=(warns.length?warns.join(' · '):'현재 가정에서 광학창 여유와 중앙선 지면 투영을 확보합니다.')+` 중앙선은 25 mm 간격 표본이며, 양 창 동시 시야 시작은 ${distance(a.centerlineBoth)}입니다. 차체·캐스터·허리·작업물 차폐, 렌즈 왜곡과 깊이 측정 가능 범위는 미포함입니다.`;$('camera-assessment').classList.toggle('warn',!!warns.length);
 };
 for(const [id,key]of inputs)$(id).addEventListener('input',()=>{const el=$(id),v=+el.value;if(!Number.isFinite(v)||v<+el.min||v>+el.max)return;cameraDesign[key]=v;window.renderCameraReview();if(window.renderRideReview)window.renderRideReview();inspector();draw();});
 for(const [id,key]of[['cam-brackets','brackets'],['cam-rays','rays']])$(id).onchange=()=>{cameraDesign[key]=$(id).checked;draw();};
 function focus(view){mechanism.scope='base';partGroup='base';window.renderMechanismReview();document.querySelectorAll('[data-group]').forEach(b=>b.classList.toggle('active',b.dataset.group==='base'));select('camera');zoom=1;setView(view);$('model').scrollIntoView({block:'center'});}
 $('camera-iso').onclick=()=>focus('iso');$('camera-top').onclick=()=>focus('top');$('camera-side-view').onclick=()=>focus('side');
 $('camera-previous').onclick=()=>{cameraDesign={...cameraDefaults,inset:35,spacing:160};window.renderCameraReview();if(window.renderRideReview)window.renderRideReview();inspector();draw();};
 $('camera-reset').onclick=()=>{cameraDesign={...cameraDefaults};window.renderCameraReview();if(window.renderRideReview)window.renderRideReview();inspector();draw();};
 window.renderCameraReview();mechanism.scope='base';partGroup='base';window.renderMechanismReview();document.querySelectorAll('[data-group]').forEach(b=>b.classList.toggle('active',b.dataset.group==='base'));select('camera');yaw=.95;elevation=.58;zoom=1;draw();
})();
